import unittest
from src.transplant_twin.domain.units import convert

class TestUnitsConversion(unittest.TestCase):
    def test_convert_mg_to_mg(self):
        self.assertAlmostEqual(convert(100, 'mg', 'mg'), 100.0)

    def test_convert_mg_to_ug(self):
        self.assertAlmostEqual(convert(100, 'mg', 'µg'), 100000.0)

    def test_convert_mg_to_ng(self):
        self.assertAlmostEqual(convert(100, 'mg', 'ng'), 100000000.0)

    def test_convert_mg_to_mg_per_l(self):
        self.assertAlmostEqual(convert(100, 'mg', 'mg/L'), 100.0)

    def test_convert_mg_to_ng_per_ml(self):
        self.assertAlmostEqual(convert(100, 'mg', 'ng/mL'), 100000.0)

    def test_convert_mg_per_l_to_mg(self):
        self.assertAlmostEqual(convert(100, 'mg/L', 'mg'), 100.0)

    def test_convert_mg_per_l_to_ng_per_ml(self):
        self.assertAlmostEqual(convert(100, 'mg/L', 'ng/mL'), 100000.0)

    def test_convert_mg_per_ml_to_mg(self):
        self.assertAlmostEqual(convert(100, 'ng/mL', 'mg'), 100000.0)

    def test_convert_mg_per_ml_to_mg_per_l(self):
        self.assertAlmostEqual(convert(100, 'ng/mL', 'mg/L'), 100.0)

    def test_convert_unknown_unit(self):
        with self.assertRaises(ValueError):
            convert(100, 'mg', 'g')

    def test_convert_cross_dimension(self):
        with self.assertRaises(ValueError):
            convert(100, 'mg/L', 'ng/mL')

    def test_convert_nan_value(self):
        with self.assertRaises(ValueError):
            convert(float('nan'), 'mg', 'mg')

    def test_convert_inf_value(self):
        with self.assertRaises(ValueError):
            convert(float('inf'), 'mg', 'mg')

if __name__ == '__main__':
    unittest.main()
